  5	/**
  6	 * Returns true if the given WP status is terminal (no further transitions out).
  7	 * Terminal statuses: COMPLETE, CANCELLED.
  8	 *
  9	 * Use this predicate everywhere you need to check whether a WP is "done" —
 10	 * instead of inline `status === 'COMPLETE'` or `status !== 'COMPLETE'` checks —
 11	 * so that adding a new terminal status in the future is a single-point change.
 12	 */
 13	export function isTerminalStatus(status: string): boolean {
 14	  return status === 'COMPLETE' || status === 'CANCELLED';
 15	}
