 17	/**
 18	 * Status transition rules enforced by the MCP server.
 19	 * Based on the transition table in plan.md:
 20	 *
 21	 * Legal transitions:
 22	 * - READY -> IN_PROGRESS (if dependencies met)
 23	 * - READY -> BLOCKED
 24	 * - READY -> CANCELLED (PM only)
 25	 * - IN_PROGRESS -> COMPLETE (if all acceptance criteria met)
 26	 * - IN_PROGRESS -> BLOCKED
 27	 * - IN_PROGRESS -> CANCELLED (PM only)
 28	 * - IN_PROGRESS -> READY (unclaim path, spec §21.13)
 29	 * - BLOCKED -> IN_PROGRESS
 30	 * - BLOCKED -> READY (auto-unblock by propagateDependencyUnblock)
 31	 * - BLOCKED -> CANCELLED (PM only)
 32	 * - COMPLETE -> IN_PROGRESS (triggers revision increment)
 33	 * - COMPLETE -> CANCELLED (PM only)
 34	 * - CANCELLED is terminal — no transitions out (including CANCELLED -> CANCELLED)
 35	 */
 36	export function isValidStatusTransition(
 37	  from: WorkPackageStatus,
 38	  to: WorkPackageStatus
 39	): boolean {
 40	  // Same-status is a no-op for all statuses except CANCELLED (which is terminal).
 41	  if (from === to) {
 42	    return from !== 'CANCELLED';
 43	  }
 44	
 45	  switch (from) {
 46	    case 'READY':
 47	      return to === 'IN_PROGRESS' || to === 'BLOCKED' || to === 'CANCELLED';
 48	
 49	    case 'IN_PROGRESS':
 50	      return to === 'COMPLETE' || to === 'BLOCKED' || to === 'CANCELLED' || to === 'READY';
 51	
 52	    case 'BLOCKED':
 53	      return to === 'IN_PROGRESS' || to === 'READY' || to === 'CANCELLED';
 54	
 55	    case 'COMPLETE':
 56	      return to === 'IN_PROGRESS' || to === 'CANCELLED';
 57	
 58	    case 'CANCELLED':
 59	      return false; // Terminal — no transitions out
 60	
 61	    default:
 62	      return false;
 63	  }
 64	}
